159	fn artifact_memories_for_phase2(
160	    selection: &codex_state::Phase2InputSelection,
161	) -> Vec<Stage1Output> {
162	    let mut seen = HashSet::new();
163	    let mut memories = selection.selected.clone();
164	    for memory in &selection.selected {
165	        seen.insert(rollout_summary_file_stem(memory));
166	    }
167	    for memory in &selection.previous_selected {
168	        if seen.insert(rollout_summary_file_stem(memory)) {
169	            memories.push(memory.clone());
170	        }
171	    }
172	    memories
173	}
